// Corta la respuesta del agente en burbujas. El origen usaba un LLM para esto
// (Message a model1, 13 KB de prompt). Acá es determinístico: mismo criterio de corte
// —párrafos— pero sin una llamada más ni la variabilidad de un modelo.
// REGLA HEREDADA: una cotización y el bloque de los 7 pasos NUNCA se parten.
const ctx = $('Normalizar entrada').first().json;
const salida = $input.first().json;
let txt = String(salida.output ?? salida.text ?? '').trim();
if (!txt) throw new Error('W6: el agente no devolvió texto');

// El modelo a veces envuelve toda la respuesta entre comillas (rectas o tipográficas)
// y eso llegaba al cliente tal cual: la primera burbuja abría con « y la última
// cerraba con ». En el origen lo absorbía el splitter LLM; acá hay que sacarlo.
const PAR = [['"', '"'], ['“', '”'], ["'", "'"], ['«', '»']];
for (const [a, b] of PAR) {
  if (txt.length > 1 && txt.startsWith(a) && txt.endsWith(b)) {
    txt = txt.slice(a.length, -b.length).trim();
    break;
  }
}

// ── MARCADOR DE PAGO (va ANTES de partir en burbujas) ────────────────────────────────────────────────────────────
// El prompt del Recolector le pide emitir `url1234.com123` para mandar los datos
// bancarios. En Kommo ese marcador lo interceptaba un salesbot; en GHL no hay
// salesbots y se midió que NINGÚN nodo de los 11 workflows lo procesaba, así que le
// llegaba al cliente como texto literal y el PDF nunca salía. Acá se resuelve: se
// saca el marcador del texto y se adjunta el PDF *NUMEROS DE CUENTA*.
//
// El orden importa y es el reclamo textual de Oscar: primero los datos de pago,
// después el comprobante.
//
// ⚠️ ESTE BLOQUE VA ANTES DE ARMAR `partes`. La primera versión lo puso después y el
// marcador le llegaba igual al cliente: el PDF se adjuntaba bien, pero `partes` ya se
// había construido con el `txt` sin limpiar. Si el PDF no está en la caché, el marcador
// se saca igual —
// un mensaje sin adjunto es malo, pero "url1234.com123" en el chat es peor.
const MARCADOR = /\s*(?:el\s+siguiente\s+URL\s*:?\s*)?url1234\.com123\s*/gi;
const _le2 = $('Leer evento');
const pdfPago = _le2.isExecuted
  ? ((_le2.first().json || {}).pdf_pago || null) : null;
const teniaMarcador = MARCADOR.test(txt);
MARCADOR.lastIndex = 0;
if (teniaMarcador) {
  // El agente a veces envuelve el marcador en un link markdown: "[ ](url1234.com123)".
  // Si sólo se saca el marcador queda el cascarón "[ ]()" en el mensaje del cliente
  // (reportado el 14/08), y el limpiador de links de más abajo no lo agarra porque su
  // regex exige http. Por eso el link entero se saca ACÁ, antes que el marcador suelto.
  txt = txt.replace(/\[[^\]]*\]\([^)]*url1234\.com123[^)]*\)/gi, ' ');
  txt = txt.replace(MARCADOR, ' ')
           // cualquier otro cascarón de link vacío que haya quedado, venga de donde venga
           .replace(/\[[^\]]*\]\(\s*\)/g, ' ')
           // el marcador suele venir incrustado en una frase ("...los datos: url1234.com123,
           // ¡súper fácil!"), así que al sacarlo queda puntuación huérfana. Sin esto la
           // burbuja le llega al cliente empezando con ", " — se vio en producción.
           .replace(/^[\s,;:.\-–—]+/, '')
           .replace(/\s+([,;:.!?])/g, '$1')
           // Dos signos seguidos: el agente presenta el marcador con dos puntos
           // ("...para el pago del anticipo: [ ](url…).") y al sacarlo quedan ":."
           // pegados. Se queda el segundo. No toca "Dígame:\n- Cantidad" (después de
           // los dos puntos viene un salto y un guión, que no están en la clase) ni
           // "Total: $2,100" (viene un espacio y un símbolo).
           .replace(/([,;:])\s*([.,;:!?])/g, '$2')
           .replace(/([(¡¿])\s+/g, '$1')
           .replace(/[ \t]{2,}/g, ' ')
           .replace(/\n{3,}/g, '\n\n').trim();

  // Lo que se adjunta es un PDF, no un enlace. El prompt del Recolector le dice "URL" al
  // marcador, así que el modelo redacta "Aquí tienes el enlace para realizar el pago" y al
  // lead le llega esa frase con un PDF colgado (medido en el test de paridad, línea 5653).
  // El viejo dice "Aquí tiene toda la info para el pago", que describe lo que manda.
  //
  // Se corrige acá y no en el prompt porque acá se sabe DETERMINÍSTICAMENTE qué se adjunta.
  // ⚠️ La primera versión de esto exigía que "el enlace" estuviera PEGADO a "para el pago"
  // y falló 1 de 3 corridas: el modelo escribió "el enlace CON TODA LA INFORMACIÓN para
  // realizar el pago" y la regex no matcheó. No se puede enumerar cómo lo va a redactar.
  //
  // Se ataca el SUSTANTIVO, no la frase: dentro de este bloque lo que se adjunta es siempre
  // el PDF de números de cuenta, así que cualquier "enlace"/"link" acá es falso por
  // construcción. El orden de las 4 reglas importa y está probado con 8 redacciones:
  //   · la larga primero, para no dejar "la info con toda la información";
  //   · el plural CON artículo antes que el pelado, o "los enlaces" deja "los la info";
  //   · el catch-all último, que sólo ve los que quedaron sin artículo.
  txt = txt
    .replace(/\b(?:el|este|ese|un)\s+(?:enlace|link)\s+con\s+toda\s+la\s+informaci[óo]n\b/gi,
             'toda la info')
    .replace(/\b(?:los|estos|esos|unos)\s+(?:enlaces|links)\b/gi, 'la info')
    .replace(/\b(?:el|este|ese|un)\s+(?:enlace|link)\b/gi, 'la info')
    .replace(/\b(?:enlaces|links|enlace|link)\b/gi, 'la info');
}

const step = $('Elegir ruta').first().json.step;

// ── SALUDO FIJO, DETERMINÍSTICO ────────────────────────
// El saludo NO lo redacta el LLM: se le impone. El agente Starter tiene un prompt que
// dice "el mensaje no puede ser modificado bajo ninguna circumstancia" y aun así lo
// retipeaba: Oscar reportó que las opciones de evento llegaban SIN sus emojis y con un
// bullet "•" que no existe en el original, y que el emoji del saludo llegaba partido.
// Un modelo reproduciendo emojis compuestos (ZWJ + variation selector) carácter por
// carácter los rompe, y no hay forma de pedirle que no lo haga: se le saca la tarea.
//
// Los emojis de acá tienen que quedar BYTE-IDÉNTICOS a los del prompt original: son los
// únicos probados en el canal. No reescribir a mano — este literal sale de componer
// base-prod + deltas con hpf-aplicar-deltas-prompt.py.
const SALUDO_CANONICO = "Hola! gracias por escribir a *Happy Flops*, me llamo *Rebeca* soy un asistente virtual, yo le estaré atendiendo con gusto ☺️🙋‍♀\n\nMe podría decir de que es su evento? \n\n🤵👰 - *Boda*\n🎂🥳 - *XV Años*\n👼🏢 - *Otros*"

if (step === 'step_1') {
  txt = SALUDO_CANONICO;
}

// ── ASTERISCO DOBLE → SIMPLE ───────────────────────────────────────────────────
// WhatsApp y Telegram usan *texto* para negrita; **texto** es markdown y les llega
// literal, con los asteriscos a la vista. El prompt del Recolector ya lo prohíbe y aun
// así el modelo lo escribe (se midió '**Pantuflas Normales**' el 14/08), así que se
// normaliza acá: no hay criterio que delegar, el formato correcto es uno solo.
//
// Va ANTES del reemplazo de links para no pisar un [texto](url) que tenga ** adentro.
txt = txt.replace(/\*\*([^*\n]{1,120})\*\*/g, '*$1*');

// ── LINKS EN MARKDOWN → URL PELADA ─────────────────────────────────────────────
// WhatsApp no renderiza [texto](url): al cliente le llega el corchete, el paréntesis
// y la URL cruda, todo junto. Se midió sobre 5 corridas de «¿de dónde son?» que el
// agente escribe el link de Google Maps en markdown 5 de 5 veces, o sea siempre.
//
// Va por código y no por prompt porque acá no hay criterio que delegar: el formato
// correcto es uno solo, y una regla de prompt daría ~el 57% que se midió el 12/8 en el
// otro punto que se intentó resolver así. Aplica a cualquier link, no solo al de Maps.
//
// Si el texto visible del link es distinto de la URL, se conserva como etiqueta antes
// de la URL para no perder el contexto («nuestra ubicación: https://…»).
txt = txt.replace(/\[([^\]]{0,80})\]\((https?:\/\/[^\s)]+)\)/g, (_, etiqueta, url) => {
  const e = String(etiqueta).trim();
  const soloLink = !e || /^(aqu[íi]|link|enlace|ac[áa]|ver|mapa|ubicaci[óo]n)$/i.test(e);
  return soloLink ? url : `${e}: ${url}`;
});

const INDIVISIBLE = /(Cotizaci[óo]n|Anticipo|7 SENCILLOS PASOS|7 DIAS DE PROMO)/i;

// Dónde arranca el bloque de los 7 pasos. Se usa para DOS cosas: cortar ahí (acá abajo)
// y meter el video de reseñas en ese mismo borde (más abajo). Tiene que ser la MISMA
// expresión en los dos lugares o el video termina en la posición equivocada.
const RE_7PASOS = /7 SENCILLOS PASOS/i;

let partes;
if (INDIVISIBLE.test(txt)) {
  // REGLA HEREDADA: una cotización no se parte, y el bloque de los 7 pasos tampoco. Pero
  // eso NO quiere decir que vayan en la MISMA burbuja: el viejo manda la cotización y los
  // 7 pasos como mensajes separados, con la prueba social en el medio (medido en A1, C4 y
  // F5 del test de paridad del 19/08).
  //
  // Salían pegados porque `INDIVISIBLE` matchea el texto ENTERO si aparece cualquiera de
  // sus marcas, y `partes = [txt]` dejaba una sola burbuja gigante con cotización + cierre
  // + 7 pasos. Se corta SÓLO en ese borde y cada bloque queda intacto.
  const m7 = txt.match(RE_7PASOS);
  let corte = null;
  if (m7 && m7.index > 0) {
    // Cortar al principio de la LÍNEA que contiene la marca, no en la marca misma: si no,
    // "¡HAZ TU PEDIDO EN " queda colgando al final de la cotización.
    const ini = txt.lastIndexOf('\n', m7.index);
    corte = ini < 0 ? 0 : ini + 1;
  }
  if (corte) {
    const antes = txt.slice(0, corte).trim();
    const desde = txt.slice(corte).trim();
    partes = (antes && desde) ? [antes, desde] : [txt];
  } else {
    partes = [txt];                                // entero, sin cortar
  }
} else {
  partes = txt.split(/\n\s*\n/).map(s => s.trim()).filter(Boolean);
  // el origen mandaba como máximo 3 burbujas
  if (partes.length > 3) {
    partes = [partes[0], partes[1], partes.slice(2).join('\n\n')];
  }
  if (partes.length === 0) partes = [txt];
}

const pasos = (salida.intermediateSteps || []).map(s => s?.action?.tool).filter(Boolean);

// step_3 con respuesta especial: el lead ya recibió las fichas y ahora recibe además
// la respuesta del Recolector. Las burbujas del catálogo van PRIMERO, como en el
// origen (Loop Over Items manda las fichas, y recién después corre el Recolector).
// isExecuted es obligatorio: en step_4 este nodo no corrió y referenciarlo tira
// ExpressionError, que se llevaría puesto el turno entero.
const ca = $('Cards a partes');
const fichas = ca.isExecuted ? (ca.first().json.partes || []) : [];
// Si en este mismo turno el Recolector YA cotizó, la pregunta de cantidad y código
// postal que `Cards a partes` agrega en step_3 sobra: el lead ya dio los dos datos.
// Reportado el 14/08 — pedía cantidad y CP y acto seguido mandaba la cotización con
// esos mismos números.
//
// Se reusa la regex INDIVISIBLE, que ya identifica una cotización, en vez de inventar
// otra. Ojo que matchea "Cotizacion"/"Cotización" pero NO "cotizar": un "decime la
// cantidad para cotizarte" no cuenta como cotización hecha, y ahí el CTA sí debe salir.
const yaCotizo = INDIVISIBLE.test(txt);
const fichasFinales = yaCotizo
  ? fichas.filter(p => !/Le interesa sumarlos a la cotizaci/i.test(p.texto || ''))
  : fichas;

const partesFinales = fichasFinales.concat(partes.map(p => (typeof p === 'string'
  ? { texto: p, adjuntos: [] } : p)));

// ── VIDEO DE RESEÑAS, ANTES DE LOS 7 PASOS ─────────────────────────────────────
// Oscar (11/08): "antes de enviar los pasos, haz tu pedido en 7 pasos, envía el
// salesbot de video reseña de confianza". En Kommo era el salesbot 62110; en GHL no
// hay salesbots, así que el paso no existía.
//
// Se dispara con el bloque de los 7 pasos, que es exactamente donde Oscar lo pidió, y
// se inserta DESPUÉS de las fichas de producto y ANTES del texto del agente.
//
// ⚠️ La cardinalidad va atada al mensaje de los 7 pasos: si el agente lo repitiera en
// una misma conversación, el video saldría de nuevo. El prompt del Recolector ya dice
// "no mandes reiteradas veces el mensaje de los 7 pasos", así que hoy no pasa; si
// alguna vez pasa, se arregla ahí y no acá.
const VIDEO_RESENAS = 'https://assets.cdn.filesafe.space/onRwi0ZF4uYi0Lp6GAbE/media/6a7e351ca6a03cda06c8508c.mp4';
const TEXTO_RESENAS = 'Sabemos que comprar por internet puede generar desconfianza… 😰\n\n'
  + 'Con HAPPY FLOPS, tienes la SEGURIDAD de que TODO es CONFIABLE, aquí puedes ver '
  + 'lo que dicen nuestros clientes en Facebook ⭐⭐⭐⭐⭐';
if (RE_7PASOS.test(txt)) {
  // Va JUSTO ANTES de la burbuja de los 7 pasos, no antes del texto del agente.
  //
  // El splice en `fichasFinales.length` ponía el video en la posición 0 cuando el turno no
  // traía fichas — que es exactamente el turno de la cotización —, así que la prueba social
  // salía ANTES de cotizar. El viejo cotiza y DESPUÉS tranquiliza.
  //
  // No contradice a Oscar (11/08, "antes de enviar los pasos"): los dos criterios apuntan
  // al mismo lugar, entre la cotización y los 7 pasos.
  const i7 = partesFinales.findIndex(p => RE_7PASOS.test(p.texto || ''));
  partesFinales.splice(i7 >= 0 ? i7 : partesFinales.length, 0,
    { texto: TEXTO_RESENAS, adjuntos: [VIDEO_RESENAS] });
}

// El PDF de los datos bancarios se cuelga de la última burbuja del agente (no de las
// fichas del catálogo, que van primero y son de producto). Así el cliente recibe el
// texto del cierre y los números de cuenta juntos, en un mismo mensaje.
if (teniaMarcador && pdfPago && partesFinales.length) {
  const ult = partesFinales[partesFinales.length - 1];
  ult.adjuntos = (ult.adjuntos || []).concat([pdfPago]);
}

// Etapa destino. W6 decide, W1 escribe.
//   step_1 → Saludo Enviado. NOTA: es capacidad NUEVA. En Kommo la ETAPA 1 se LEE
//     (If8, If21) pero ningún nodo de n8n la escribe; el saludo salía por salesbots
//     cuyo cuerpo no está en el export, así que quién la escribía no es verificable
//     desde el repo. En GHL no hay salesbots: si no la escribe W1, no la escribe nadie.
//   step_4 → Cotizado SÓLO si el Recolector realmente cotizó. Es la condición `If4`
//     del origen (`output` contains "7 DIAS DE PROMO") antes de mover a ETAPA 4. Un
//     "¿cuánto sale un cilindro?" ruteado a step_4 NO avanza la etapa. Se reusa la
//     misma regex INDIVISIBLE de arriba en vez de inventar otra.
let etapa_destino = null;
if (step === 'step_1') etapa_destino = 'Saludo Enviado';
else if (step === 'step_3') etapa_destino = INDIVISIBLE.test(txt)
  ? 'Cotizado' : 'Productos Mostrados';
else if (step === 'step_4' && INDIVISIBLE.test(txt)) etapa_destino = 'Cotizado';

return [{ json: {
  ok: true,
  sessionId: ctx.sessionId, contactId: ctx.contactId,
  step,
  partes: partesFinales,
  tools_usadas: fichas.length ? ['CATALOGO'].concat(pasos) : pasos,
  texto_completo: txt,
  etapa_destino,
  // Trazas del cierre de pago, para poder auditar en las ejecuciones si el PDF salió.
  pago_marcador: teniaMarcador,
  pago_pdf: teniaMarcador ? (pdfPago || null) : null,
} }];

