parameters.jsCode:
// Las cards del catálogo se convierten en burbujas: texto + su asset.
const ctx = $('Normalizar entrada').first().json;
const r = $input.first().json;
const step = $('Elegir ruta').first().json.step;
const cards = r.cards || [];
// El texto de la burbuja es la DESCRIPCIÓN de la ficha, nunca su nombre. El nombre
// ('Cilindros video', 'Catalogo pantuflas', 'vaca') es la etiqueta interna del catálogo
// y no es copy de cara al cliente: 24 de las 65 fichas no tienen descripción, así que
// el fallback al nombre se las mostraba a todas. Reportado el 14/08 sobre el video de
// cilindros, que llegaba con 'Cilindros video' escrito debajo.
//
// Sin descripción el asset viaja solo, que es exactamente lo que se quiere en los videos.
// El filtro final descarta una ficha que no tenga NI texto NI asset, para no mandar una
// burbuja vacía.
const partes = cards.map(c => ({
  texto: c.texto || '',
  adjuntos: c.media_url ? [c.media_url] : [],
})).filter(p => p.texto || p.adjuntos.length);

// El texto que acompaña a las fichas. Sin esto el lead recibe fotos y ninguna
// palabra: el oráculo muestra que el origen SIEMPRE mandaba un texto además de
// los assets (sample_1 T6 y T10, sample_9 T6 y T10).
//
//  · step_2 — la reacción al evento + la promo de 7 días, ANTES de la imagen
//    principal. En el origen viajaba por el salesbot 60862 de Kommo, fuera de
//    n8n; acá se usa el `texto_dinamico` que el propio Main Image ya genera y
//    que hasta ahora se descartaba.
//  · step_3 — el pedido de cantidad y código postal, DESPUÉS de las fichas.
//    En el origen es un texto FIJO, hardcodeado en el nodo `actualizar23`: no
//    sale del agente. Se replica literal.
//
// El orden (antes en step_2, después en step_3) sale de la semántica de cada
// texto, no de la topología del origen: allá los dos salían por ramas paralelas
// de Kommo y el orden real no es observable desde el grafo. Queda declarado.
// Negritas y emoji pedidos por Oscar en la reunión del 2026-08-11: en México el texto
// pelado se lee mal y él lo señaló sobre este mensaje en particular. El formato es el de
// WhatsApp (*asterisco simple*), igual que la promo del Main Image. El texto en sí no
// cambia — sigue siendo el fijo que el origen tenía hardcodeado en `actualizar23`.
const CTA_STEP_3 = '¿Le interesa sumarlos a la cotización? 😊\n' +
  'Dígame:\n- *Cantidad*\n- *Código postal*\n\n¡Gracias!';

// El texto_dinamico no viene de W3 (que sólo sabe de fichas) sino del agente. Se lo
// pide al nodo lector, chequeando isExecuted: referenciar un nodo que no corrió en
// esta rama tira ExpressionError y se lleva puesto el turno entero.
let dinamico = '';
if (step === 'step_2') {
  const li = $('Leer Main Image');
  dinamico = String((li.isExecuted ? li.first().json.texto_dinamico : '') || '').trim();
}

// ¿W3 no trajo NINGUNA ficha para este evento x producto? Entonces no hay nada que "sumar
// a la cotización" y el CTA queda colgando: el lead recibe una pregunta sobre unas fichas
// que nunca vio. Pasa cuando el producto no existe para ese evento (vasos en Otros,
// mandiles en XV).
//
// En ese caso no se emite NADA acá: contesta el Recolector, que sí tiene el dato en el
// prompt (Vasos popote $35, mínimo 50, con ejemplo de cotización). Es lo que hace el viejo
// en E3. Para que eso ocurra, `¿Requiere cotizar?` tiene una condición OR sobre este mismo
// flag — los dos cambios van juntos y no tiene sentido uno sin el otro.
const sin_fichas = cards.length === 0;

if (step === 'step_2' && dinamico) {
  partes.unshift({ texto: dinamico, adjuntos: [] });
} else if (step === 'step_3' && !sin_fichas) {
  partes.push({ texto: CTA_STEP_3, adjuntos: [] });
}

// Este fallback era INALCANZABLE en step_3: el push del CTA garantizaba length >= 1 y la
// condición no se evaluaba nunca como verdadera. Ahora sí es alcanzable, pero se excluye el
// caso `sin_fichas` a propósito — ahí contesta el Recolector con el dato real, y un
// "déjame revisar eso" encima sería peor que no decir nada.
if (partes.length === 0 && !sin_fichas) {
  partes.push({ texto: 'Déjame revisar eso y te confirmo.', adjuntos: [] });
}
return [{ json: {
  ok: true, sessionId: ctx.sessionId, contactId: ctx.contactId,
  step, partes, sin_media: r.sin_media || [], tools_usadas: ['CATALOGO'],
  // Lo lee `¿Requiere cotizar?` para forzar el paso por el Recolector.
  sin_fichas,
  // El evento viaja para que los seguimientos puedan interpolarlo en sus textos
  // (las olas 1 y 3 de la campaña `imagen` dicen "vi que me comentaste {evento}").
  evento: r.evento || null,
  // W6 decide la etapa, W1 la escribe. Réplica de seg-imagen (ETAPA 2) y
  // seg-cotizacion (ETAPA 3) del origen, que avanzan sin condición.
  etapa_destino: step === 'step_2' ? 'Evento Identificado' : 'Productos Mostrados',
} }];

function leerJSON(entrada) {
  let v = entrada;
  if (v && typeof v === 'object' && 'output' in v) v = v.output;
  if (typeof v === 'string') {
    let t = v.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    const i = t.indexOf('{'), f = t.lastIndexOf('}');
    if (i >= 0 && f > i) t = t.slice(i, f + 1);
    try { v = JSON.parse(t); } catch (e) { return null; }
  }
  if (!v || typeof v !== 'object' || Array.isArray(v)) return null;
  if (v.output && typeof v.output === 'object') v = v.output;   // doble envoltura
  // El prompt de Products escribe la clave CON TILDE ("subcategoría"); el resto del
  // sistema la usa sin tilde. Se aceptan las dos en vez de perder el filtro.
  if (v['subcategoría'] !== undefined && v.subcategoria === undefined) {
    v.subcategoria = v['subcategoría'];
  }
  return Object.keys(v).length ? v : null;
}

// Toma la traducción del canonicalizador y la deja lista para W3. Si por lo que sea
// no devolvió una lista usable, se sigue con los nombres crudos del agente: perder
// precisión en el match es malo, quedarse sin mostrar nada es peor — y el origen
// tampoco corta acá.
const previo = $('Leer Products').first().json;
const o = leerJSON(($input.first().json || {}).message?.content) || {};
let productos = o.productos ?? [];
if (typeof productos === 'string') {
  const t = productos.trim();
  try { productos = t.startsWith('[') ? JSON.parse(t) : (t ? [t] : []); }
  catch (e) { productos = t ? [t] : []; }
}
if (!Array.isArray(productos)) productos = productos ? [productos] : [];
productos = productos.map(p => String(p).trim()).filter(Boolean);

const _txtLead = String(previo.texto || '').toLowerCase();

// ── R10: no arrastrar productos de turnos anteriores ─────────────────────────────────
// Sólo se filtra si el mensaje ACTUAL nombra algún producto. Si no nombra ninguno
// ("cuánto cuestan?", "dale"), el arrastre es CORRECTO: el lead se refiere a lo último
// ofrecido. Y si el filtro dejaría la lista VACÍA se conserva la original.
const _FAM = [
  ['sandalias', /sandalia|zandalia|sandalea|chancla/],
  ['cilindros', /cilindro|silindro/],
  ['mandiles',  /mandil|delantal/],
  ['anticruda', /anticrud|anticrur|costalit|costale|costal\b/],
  ['pantuflas', /pantufla|pantus|pantofla/],
  ['vasos',     /vaso|popote/],
];
const _nombradas = _FAM.filter(([, re]) => re.test(_txtLead)).map(([f]) => f);
if (_nombradas.length) {
  const _famDe = (p) => (_FAM.find(([, re]) => re.test(String(p).toLowerCase())) || [null])[0];
  const _soloPedidos = productos.filter(p => _nombradas.includes(_famDe(p)));
  if (_soloPedidos.length && _soloPedidos.length !== productos.length) {
    console.log('R10 arrastre recortado:', productos, '->', _soloPedidos, '| nombradas:', _nombradas);
    productos = _soloPedidos;
  }
}

// ── Cobertura de pantufla: DECIDE EL PEDIDO (array `productos`), NO el texto del turno ──
// Fix 27/8 (Camilo). Tres materiales distintos, cada uno con su cobertura EXACTA (Oscar):
//   • peluche      → SÓLO la ficha de peluche + video (SIN catálogo: el catálogo es de
//                    diseños de satín y no aplica a la de peluche).
//   • moño satín   → SÓLO la ficha de moño satín + catálogo + video (SIN la lisa ni la de
//                    peluche). El catálogo y el video los agrega W3 por ROL.
//   • genérico     → todas las variantes (lisa + moño satín + moño peluche) + catálogo + video.
//   • evento Otros → siempre genérico: no hay fichas de variantes cargadas para ese evento.
// El material se decide mirando primero el TEXTO del turno (más confiable) y, si el texto
// calla, el propio pedido — porque el término específico ('pantuflas mono satin' /
// 'pantuflas mono peluche') puede venir del LLM por CONTEXTO en un turno cuyo texto no
// nombra el material (ej. "cuánto cuestan"), que es lo que hacía caer video/catálogo.
const _rePantuflaTerm = /pantufla|pantus|pantofla/i;
const _ESPECIFICA = /^pantuflas mono (peluche|satin)$/i;
const _GENERICA   = /^pantuflas( mono)?$/i;
const _reMonoSatin = /mono\s*sat[ií]?n/i;

const _pidioMaterial    = /peluche|satin|sat[ií]n/.test(_txtLead);
const _mencionaPantufla = _rePantuflaTerm.test(_txtLead);
const _tienePantuflaTerm = productos.some(p => _rePantuflaTerm.test(p));
const _hayPantufla = _tienePantuflaTerm || _mencionaPantufla || _pidioMaterial;

const _txtPeluche = /peluche/.test(_txtLead);
const _txtSatin   = /satin|sat[ií]n/.test(_txtLead);
const _txtGen     = _mencionaPantufla && !_txtPeluche && !_txtSatin;
const _prodPeluche       = productos.some(p => /peluche/i.test(p));
const _prodMonoSatin     = productos.some(p => _reMonoSatin.test(p));
const _prodGenerico      = productos.some(p => _GENERICA.test(p));
const _prodPantuflaNoPel = productos.some(p => _rePantuflaTerm.test(p) && !/peluche/i.test(p));
const _evOtros = /otros/i.test(String(previo.evento || ''));

// Categoría de material. Texto primero; si el texto calla, decide el pedido.
let _cat;
if (_txtPeluche) _cat = 'peluche';
else if (_txtSatin) _cat = 'satin';
else if (_txtGen) _cat = 'generico';
else if (_prodPeluche && !_prodPantuflaNoPel) _cat = 'peluche';
else if (_prodMonoSatin && !_prodGenerico) _cat = 'satin';
else _cat = 'generico';

const _antes = productos.slice();
if (_hayPantufla) {
  if (_evOtros) {
    // Otros: sin variantes cargadas → genérico (info + catálogo + video, únicos que existen).
    productos = productos.filter(p => !_ESPECIFICA.test(p));
    if (!productos.some(p => _GENERICA.test(p))) productos.push('pantuflas');
  } else if (_cat === 'peluche') {
    // Peluche: SÓLO la ficha de peluche. El catálogo de moño y el video de moño los agrega
    // W3 por ROL. Ya NO se manda 'pantuflas video' (ese es el video COMPARTIDO/lisa, no el
    // de moño); si se mandara, la peluche recibiría además el video que no le corresponde.
    productos = productos.filter(p => !/pantufla/i.test(p) || /peluche/i.test(p));
    if (!productos.some(p => /^pantuflas mono peluche$/i.test(p))) productos.push('pantuflas mono peluche');
  } else if (_cat === 'satin') {
    // Moño satín: SÓLO la ficha de moño satín. W3 agrega catálogo + video por ROL.
    productos = productos.filter(p => !/pantufla/i.test(p) || _reMonoSatin.test(p));
    if (!productos.some(p => /^pantuflas mono satin$/i.test(p))) productos.push('pantuflas mono satin');
  } else {
    // Genérico: todas las variantes (el término 'pantuflas' matchea las tres + catálogo + video).
    productos = productos.filter(p => !_ESPECIFICA.test(p));
    if (!productos.some(p => _GENERICA.test(p))) productos.push('pantuflas');
  }
}
if (productos.length !== _antes.length) {
  console.log(`pantuflas: cat=${_cat} otros=${_evOtros} txt="${_txtLead}"`, _antes, '->', productos);
}
if (!productos.length) productos = _antes;

return [{ json: { ...previo,
  productos: productos.length ? productos : previo.productos,
  productos_crudos: previo.productos,
  subcategoria: o.subcategoria || previo.subcategoria,
  canonicalizado: productos.length > 0 } }];

function leerJSON(entrada) {
  let v = entrada;
  if (v && typeof v === 'object' && 'output' in v) v = v.output;
  if (typeof v === 'string') {
    let t = v.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    const i = t.indexOf('{'), f = t.lastIndexOf('}');
    if (i >= 0 && f > i) t = t.slice(i, f + 1);
    try { v = JSON.parse(t); } catch (e) { return null; }
  }
  if (!v || typeof v !== 'object' || Array.isArray(v)) return null;
  if (v.output && typeof v.output === 'object') v = v.output;   // doble envoltura
  // El prompt de Products escribe la clave CON TILDE ("subcategoría"); el resto del
  // sistema la usa sin tilde. Se aceptan las dos en vez de perder el filtro.
  if (v['subcategor\u00eda'] !== undefined && v.subcategoria === undefined) {
    v.subcategoria = v['subcategor\u00eda'];
  }
  return Object.keys(v).length ? v : null;
}

// Lee la salida del agente Products de forma tolerante y la deja PLANA para W3.
// `productos` vacío NO significa "mandale todo": significa que el agente no supo
// qué mostrar. El origen tiene tres defensas para eso (`Is_Products_Empty`
// reintenta, `Return_Formula` devuelve {} y el agente tiene salida de error hacia
// el Recolector); acá se resuelve con una sola: si no hay productos, contesta el
// Recolector, que es exactamente a donde degradaba el origen.
const ctx = $('Normalizar entrada').first().json;
const o = leerJSON($input.first().json) || {};
let productos = o.productos ?? [];
if (typeof productos === 'string') {
  const t = productos.trim();
  try { productos = t.startsWith('[') ? JSON.parse(t) : (t ? [t] : []); }
  catch (e) { productos = t ? [t] : []; }
}
if (!Array.isArray(productos)) productos = productos ? [productos] : [];
productos = productos.map(p => String(p).trim()).filter(Boolean);

// El evento ya NO se le pregunta al LLM si el estado lo tiene resuelto. Products lo
// re-derivaba de la memoria en cada turno y derrapaba a "Boda" (12 de sus 13 ejemplos
// usan Boda), así que una conversación de XV recibía fichas de Boda a mitad de camino
// mientras otras fichas del mismo turno venían bien. El LLM queda como respaldo sólo
// para el turno en que todavía no hay estado.
//
// `Leer evento` va INTERCALADO en la cadena principal (Normalizar entrada → Leer evento →
// Router) y no en una rama paralela. El primer intento lo puso en paralelo y no funcionó:
// con executionOrder v1, n8n recorre la rama del Router hasta el final antes de volver a
// la otra, así que acá isExecuted daba false y el estado se ignoraba siempre. Se midió
// sobre 6 ejecuciones: el nodo devolvía Boda/XV bien y evento_desde_estado era False en
// todas. El isExecuted se conserva igual como cinturón, no como mecanismo.
const _le = $('Leer evento');
const _eventoEstado = _le.isExecuted
  ? String((_le.first().json || {}).evento || '').trim() : '';
const _eventoLLM = String(o.evento || '').trim();

return [{ json: { ...ctx, step: $('Elegir ruta').first().json.step,
                  evento: _eventoEstado || _eventoLLM,
                  evento_llm: _eventoLLM,
                  evento_desde_estado: !!_eventoEstado,
                  subcategoria: o.subcategoria || null,
                  productos,
                  texto_dinamico: o.texto_dinamico || '',
                  hay_productos: productos.length > 0 } }];

function leerJSON(entrada) {
  let v = entrada;
  if (v && typeof v === 'object' && 'output' in v) v = v.output;
  if (typeof v === 'string') {
    let t = v.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    const i = t.indexOf('{'), f = t.lastIndexOf('}');
    if (i >= 0 && f > i) t = t.slice(i, f + 1);
    try { v = JSON.parse(t); } catch (e) { return null; }
  }
  if (!v || typeof v !== 'object' || Array.isArray(v)) return null;
  if (v.output && typeof v.output === 'object') v = v.output;   // doble envoltura
  // El prompt de Products escribe la clave CON TILDE ("subcategoría"); el resto del
  // sistema la usa sin tilde. Se aceptan las dos en vez de perder el filtro.
  if (v['subcategor\u00eda'] !== undefined && v.subcategoria === undefined) {
    v.subcategoria = v['subcategor\u00eda'];
  }
  return Object.keys(v).length ? v : null;
}

// Lee la salida del agente Main Image de forma tolerante y la deja PLANA para W3.
const ctx = $('Normalizar entrada').first().json;
const o = leerJSON($input.first().json) || {};
const evento = String(o.evento || '').trim();
if (!evento) {
  // Corto acá en vez de dejar que W3 reciba evento vacío: con el filtro vacío
  // devuelve el catálogo entero de los tres eventos.
  throw new Error('Main Image sin evento: el agente no devolvió JSON legible');
}
return [{ json: { ...ctx, step: $('Elegir ruta').first().json.step,
                  evento, texto_dinamico: o.texto_dinamico || '' } }];

function leerJSON(entrada) {
  let v = entrada;
  if (v && typeof v === 'object' && 'output' in v) v = v.output;
  if (typeof v === 'string') {
    let t = v.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    const i = t.indexOf('{'), f = t.lastIndexOf('}');
    if (i >= 0 && f > i) t = t.slice(i, f + 1);
    try { v = JSON.parse(t); } catch (e) { return null; }
  }
  if (!v || typeof v !== 'object' || Array.isArray(v)) return null;
  if (v.output && typeof v.output === 'object') v = v.output;   // doble envoltura
  // El prompt de Products escribe la clave CON TILDE ("subcategoría"); el resto del
  // sistema la usa sin tilde. Se aceptan las dos en vez de perder el filtro.
  if (v['subcategor\u00eda'] !== undefined && v.subcategoria === undefined) {
    v.subcategoria = v['subcategor\u00eda'];
  }
  return Object.keys(v).length ? v : null;
}

// El Router devuelve {step: "step_N"}.
//
// Corrección al comentario anterior: el origen NO defaultea a step_4 "ante cualquier
// cosa rara". Su `Switch1` no tiene fallbackOutput y su única red es la regla 4 con
// `{{ $json.output.step || "step_4" }}`, que sólo cubre valores falsy. Con un step
// inválido pero no vacío (step_5, paso_3) el item MUERE ahí y el lead se queda sin
// respuesta, con la ejecución en verde. Acá se normaliza a step_4 a propósito: es
// más robusto que el origen, y queda declarado como tal.
const ctx = $('Normalizar entrada').first().json;
const o = leerJSON($input.first().json);
let step = (o && o.step) || 'step_4';
step = String(step).trim();
if (!/^step_[1-4]$/.test(step)) step = 'step_4';

// Primer contacto → saludo, sin importar lo que diga el Router. Es el
// `Exist_Interaction?` del origen, que manda al Starter sin pasar por el Router.
//
// Lo que cambió respecto de la versión rota: `primer_contacto` ya NO sale de la
// etapa del pipeline (que nadie movía, así que el bot re-saludaba para siempre —
// medido el 2026-08-07: 3 turnos seguidos, 3 saludos), sino de contar los turnos
// humanos de la sesión en `n8n_chat_histories`. Esa señal se auto-conmuta: la
// memoria escribe el turno apenas el agente contesta.
if (ctx.primer_contacto) step = 'step_1';
return [{ json: { ...ctx, step } }];

// Entrada desde W1 (o desde el webhook de prueba, mismo shape).
const j0 = $input.first().json || {};
const porWebhook = !!(j0.body && j0.body.sessionId !== undefined);
const src = porWebhook ? j0.body : j0;
for (const k of ['sessionId', 'texto']) {
  if (src[k] === undefined) throw new Error(`W6: falta "${k}"`);
}
return [{ json: {
  _via: porWebhook ? 'webhook' : 'subworkflow',
  sessionId: String(src.sessionId),
  contactId: src.contactId ?? null,
  opportunityId: src.opportunityId ?? null,
  texto: String(src.texto),
  evento: src.evento ?? null,
  primer_contacto: !!src.primer_contacto,
  fecha: $now.setZone('America/Mexico_City').toFormat("cccc dd/LL/yyyy HH:mm"),
} }];

